-- Datenbank, wie tinyops 0.25.0 sie anlegt, mit ein paar Zeilen (Test für Migrationen, 0.45)
BEGIN TRANSACTION;
CREATE TABLE acceptance(key text not null, ref text not null, sha text not null, ts real not null, note text not null default '', env text not null default '', primary key(key, ref));
CREATE TABLE agent_runs(id integer primary key autoincrement, agent text not null, ticket text not null, project_id integer, branch text not null default '', title text not null default '', status text not null, workdir text not null default '', prompt text not null default '', note text not null default '', exit_code integer, created real not null, started real, finished real, mode text not null default '', out_branch text not null default '', wt text not null default '', taken text not null default '', question text not null default '', answered text not null default '', qa text not null default '', summary text not null default '', checks text not null default '', ack text not null default '');
INSERT INTO "agent_runs" VALUES(1,'lokal','DLP-1',7,'feature/DLP-1-x','Alter Lauf','fertig','','','',NULL,1762761600.0,NULL,NULL,'','','','','','','','Bericht aus 0.25','','');
CREATE TABLE ai_accounts(id integer primary key autoincrement, name text not null unique, kind text not null, window_hours real not null, budget real not null, unit text not null, used real not null default 0, window_start real not null default 0);
CREATE TABLE audit(id integer primary key autoincrement, ts real not null, instance text not null, actor text not null, action text not null, target text not null default '', detail text not null default '{}', ok integer not null, prev text not null, hash text not null);
CREATE TABLE audit_meta(key text primary key, value text not null);
INSERT INTO "audit_meta" VALUES('instance','9cd6b55bf8e4');
CREATE TABLE checklist(id integer primary key autoincrement, key text not null, text text not null, done integer not null default 0, pos integer not null, created real not null, done_ts real);
CREATE TABLE flow_events(id integer primary key autoincrement, ref text not null default '', key text not null, title text not null default '', kind text not null, phase integer not null, xp integer not null, text text not null default '', ts real not null);
CREATE TABLE flow_state(key text primary key, phase integer not null, max_phase integer not null, ts real not null);
CREATE TABLE focus_session(id integer primary key autoincrement, key text not null, title text not null default '', area text not null default '', activity text not null default '', planned_min integer not null, start real not null, end real, parked integer not null default 0, result text not null default '', note text not null default '');
CREATE TABLE hd_seen(key text primary key, ts real not null);
CREATE TABLE ide_wt(ref text primary key, host text not null, project_id integer not null, iid integer not null, sha text not null, path text not null, repo text not null, ts real not null);
CREATE TABLE ideas(id integer primary key autoincrement, text text not null,status text not null default 'neu', created text not null, assessment text not null default '', ticket text not null default '', draft text not null default '');
INSERT INTO "ideas" VALUES(1,'Idee aus 0.25','neu','2026-11-10T08:00:00','','','');
CREATE TABLE links(ref text primary key, ticket text not null, created text not null);
INSERT INTO "links" VALUES('7:feature/DLP-1-x','DLP-1','2026-11-10T08:00:00');
CREATE TABLE pin(id integer primary key check (id = 1), key text not null, ts real not null);
CREATE TABLE pool_items(pool_id integer not null, kind text not null, value text not null, created text not null, primary key(pool_id, kind, value));
CREATE TABLE pools(id integer primary key autoincrement, name text not null unique, created text not null);
CREATE TABLE qa_check(id text primary key, status text not null, note text not null default '', version text not null default '', hash text not null default '', ts real not null);
INSERT INTO "qa_check" VALUES('b-01','ok','','0.25.0','x',1762761600.0);
CREATE TABLE sonar_snap(scope text not null, ts real not null, vals text not null);
CREATE TABLE task_stage(key text primary key, stage text not null, updated real not null);
CREATE TABLE tasks(id integer primary key autoincrement, title text not null, created text not null);
CREATE TABLE time_draft(id text primary key, date text not null, ticket text not null, title text not null default '', project_hint text not null default '', minutes integer not null, calc_minutes integer not null default 0, text text not null default '', evidence text not null default '[]', state text not null default 'offen', edited integer not null default 0, manual integer not null default 0, reference text not null default '', message text not null default '', attempts integer not null default 0, sent real, merged_into text not null default '', updated real not null);
CREATE TABLE time_gap(id integer primary key autoincrement, key text not null, title text not null default '', start real not null, end real not null, state text not null default 'offen', area text not null default '', activity text not null default '');
CREATE TABLE time_seg(id integer primary key autoincrement, key text not null, title text not null default '', start real not null, end real, last_seen real not null, source text not null default 'fokus', area text not null default '', activity text not null default '');
INSERT INTO "time_seg" VALUES(1,'DLP-1','Alter Lauf',1762761600.0,1762765200.0,1762765200.0,'fokus','','');
CREATE TABLE ux_event(id integer primary key autoincrement, ts real not null, sess text not null, view text not null default '', kind text not null, target text not null default '', ctx text not null default '', x real, y real, extra text not null default '');
CREATE INDEX sonar_snap_scope on sonar_snap(scope, ts);
CREATE INDEX agent_runs_ticket on agent_runs(ticket);
CREATE INDEX flow_events_ref on flow_events(ref);
CREATE INDEX audit_target on audit(target, id);
CREATE TRIGGER audit_no_update before update on audit begin select raise(abort, 'audit ist nur anhängend'); end;
CREATE TRIGGER audit_no_delete before delete on audit begin select raise(abort, 'audit ist nur anhängend'); end;
CREATE INDEX time_seg_start on time_seg(start);
CREATE INDEX time_draft_date on time_draft(date);
CREATE INDEX ux_event_ts on ux_event(ts);
DELETE FROM "sqlite_sequence";
INSERT INTO "sqlite_sequence" VALUES('agent_runs',1);
INSERT INTO "sqlite_sequence" VALUES('ideas',1);
INSERT INTO "sqlite_sequence" VALUES('time_seg',1);
COMMIT;
